import sys

def to_base36(n: int) -> str:
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return chars[0]
    res = []
    while n > 0:
        res.append(chars[n % 36])
        n //= 36
    return "".join(reversed(res))

def from_base36(s: str) -> int:
    return int(s, 36)

def next_id(last_id: str) -> str:
    prefix = "ORD-"
    suffix = last_id[len(prefix):]
    num = from_base36(suffix)
    num += 1
    new_suffix = to_base36(num).zfill(4).upper()
    return prefix + new_suffix

def main():
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        sys.exit("ids.txt is empty")
    last_id = lines[-1]
    print(next_id(last_id))

if __name__ == "__main__":
    main()

