import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int, width: int = 4) -> str:
    """Convert integer to base36 string padded to `width` characters."""
    digits = []
    for _ in range(width):
        digits.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base36 string to integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def next_id(last_id: str) -> str:
    """Given the last issued id (e.g. 'ORD-243G'), return the next id."""
    suffix = last_id.strip()
    if not suffix.startswith('ORD-'):
        raise ValueError(f'unexpected id format: {last_id!r}')
    code = suffix[4:]
    n = from_base36(code)
    n += 1
    new_code = to_base36(n)
    return f'ORD-{new_code}'


def main() -> None:
    try:
        with open('ids.txt') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print('ORD-0000')
        return

    # Scan from the end for the last non-empty, non-whitespace line
    last = ''
    for line in reversed(lines):
        stripped = line.strip()
        if stripped:
            last = stripped
            break

    if not last:
        print('ORD-0000')
        return

    print(next_id(last))


if __name__ == '__main__':
    main()

